#include "gui/layout_primitives.hpp"
#include <algorithm>
#include <cmath>

namespace epochengine::gui_lib {
namespace { float sane(float v,float f) noexcept{return std::isfinite(v)?v:f;} Rect sane_rect(Rect r) noexcept{r.size.x=(std::max)(1.0f,sane(r.size.x,1));r.size.y=(std::max)(1.0f,sane(r.size.y,1));return r;} }
SplitterLayout make_splitter_layout(const SplitterLayoutOptions& o) noexcept {
    const Rect a=sane_rect(o.area);const bool v=o.axis==SplitterAxis::vertical;const float extent=v?a.size.x:a.size.y;const float thick=(std::min)(extent,(std::max)(1.0f,sane(o.thickness,7)));
    const float avail=(std::max)(0.0f,extent-thick);const float before=(std::max)(0.0f,o.min_before),after=(std::max)(0.0f,o.min_after);
    float off=avail*std::clamp(sane(o.split_fraction,.5f),0.0f,1.0f);if(before+after<=avail)off=std::clamp(off,before,avail-after);else off=std::clamp(off,0.0f,avail);
    SplitterLayout l{};l.split_offset=off;l.split_fraction=avail>0?off/avail:.5f;l.fits_minimums=before+after<=avail;
    if(v){l.before={a.position,{off,a.size.y}};l.handle={{a.position.x+off,a.position.y},{thick,a.size.y}};l.after={{a.position.x+off+thick,a.position.y},{(std::max)(0.0f,a.size.x-off-thick),a.size.y}};}
    else{l.before={a.position,{a.size.x,off}};l.handle={{a.position.x,a.position.y+off},{a.size.x,thick}};l.after={{a.position.x,a.position.y+off+thick},{a.size.x,(std::max)(0.0f,a.size.y-off-thick)}};}return l;
}
float splitter_fraction_from_point(const SplitterLayoutOptions& o,Vec2 p) noexcept {const Rect a=sane_rect(o.area);const bool v=o.axis==SplitterAxis::vertical;const float extent=v?a.size.x:a.size.y;const float thick=(std::min)(extent,(std::max)(1.0f,o.thickness));const float avail=(std::max)(0.0f,extent-thick);if(avail<=0)return .5f;const float axis=v?p.x-a.position.x:p.y-a.position.y;return std::clamp(axis/avail,0.0f,1.0f);} 
bool splitter_hit_test(const SplitterLayout& l,Vec2 p,float pad) noexcept {Rect r=l.handle;r.position.x-=pad;r.position.y-=pad;r.size.x+=2*pad;r.size.y+=2*pad;return contains(r,p);} 
ProgressBarLayout make_progress_bar_layout(const ProgressBarLayoutOptions& o) noexcept {ProgressBarLayout l{};l.track=sane_rect(o.track);const float p=(std::max)(0.0f,o.padding);l.inner={{l.track.position.x+p,l.track.position.y+p},{(std::max)(0.0f,l.track.size.x-2*p),(std::max)(0.0f,l.track.size.y-2*p)}};l.has_range=o.maximum>o.minimum;l.fraction=l.has_range?std::clamp((o.value-o.minimum)/(o.maximum-o.minimum),0.0f,1.0f):0.0f;l.fill=l.inner;if(o.direction==ProgressBarDirection::left_to_right)l.fill.size.x*=l.fraction;else if(o.direction==ProgressBarDirection::right_to_left){l.fill.position.x+=l.fill.size.x*(1-l.fraction);l.fill.size.x*=l.fraction;}else if(o.direction==ProgressBarDirection::top_to_bottom)l.fill.size.y*=l.fraction;else{l.fill.position.y+=l.fill.size.y*(1-l.fraction);l.fill.size.y*=l.fraction;}return l;}
SelectableListVisibleRange selectable_list_visible_range(const SelectableListLayoutOptions& o) noexcept {const float stride=(std::max)(1.0f,o.row_height)+(std::max)(0.0f,o.row_gap);const float scroll=(std::max)(0.0f,o.scroll_offset);SelectableListVisibleRange r{};r.content_height=o.content_padding_y*2+o.row_count*stride;r.first_index=(std::min)(o.row_count,static_cast<std::uint32_t>(scroll/stride));r.past_last_index=(std::min)(o.row_count,r.first_index+static_cast<std::uint32_t>(o.viewport.size.y/stride)+2);r.has_visible_rows=r.first_index<r.past_last_index;return r;}
SelectableRowLayout make_selectable_row_layout(const SelectableListLayoutOptions& o,std::uint32_t index,Vec2 mouse,bool selected) noexcept {const float stride=(std::max)(1.0f,o.row_height)+(std::max)(0.0f,o.row_gap);SelectableRowLayout r{};r.index=index;r.row={{o.viewport.position.x,o.viewport.position.y+o.content_padding_y-o.scroll_offset+index*stride},{o.viewport.size.x,(std::max)(1.0f,o.row_height)}};r.content={{r.row.position.x+o.content_padding_x,r.row.position.y},{(std::max)(0.0f,r.row.size.x-2*o.content_padding_x),r.row.size.y}};r.visible=r.row.position.y+r.row.size.y>=o.viewport.position.y&&r.row.position.y<=o.viewport.position.y+o.viewport.size.y;r.hovered=r.visible&&contains(r.row,mouse);r.selected=selected;return r;}
std::uint32_t selectable_row_index_at(const SelectableListLayoutOptions& o,Vec2 p) noexcept {if(!contains(o.viewport,p))return invalid_selectable_row_index;const float stride=(std::max)(1.0f,o.row_height)+(std::max)(0.0f,o.row_gap);const float local=p.y-o.viewport.position.y+o.scroll_offset-o.content_padding_y;if(local<0)return invalid_selectable_row_index;const auto i=static_cast<std::uint32_t>(local/stride);return i<o.row_count?i:invalid_selectable_row_index;}
}
